class Staff {

    final String company;
    static int employeecount;
    String name;

    // Static block
    static {
        employeecount = 100;
        System.out.println("Static block executed");
    }


    // Parameterized constructor
    Staff(String name,String company) {
        this.name = name;
        this.company = company;
        employeecount++;
        System.out.println("parameterized block executed");
        // System.out.println("name: " + name);
        //  System.out.println("company: " + company);
    }

    // Non-parameterized
    Staff() {
        this.company="unknown";
        System.out.println(" non-parameterized constructor executed");
    }


}
//super
class manager extends Staff{

    manager(String name,String company) {

        super(name,company);

        System.out.println(" name: " + name);
        System.out.println("Company: " + company);
    }

    manager(){
        super();
        System.out.println("non parameterized executed");
    }



}


public class self {

    public static void main(String[] args) {

        manager m1 = new manager("ravi","abc company");
        manager m2 = new manager();
        System.out.println("Employee Count: " + manager.employeecount);
    }
}
